package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.ClientCredentialsScopesVO;

class ClientCredentialsScopesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of client credentials scopes of oauth client")
  void test_client_credentials_scopes_value_holder_assign_plain_value() {
    Object holder = new Object();
    ClientCredentialsScopesValueHolder<Object> value =
        new ClientCredentialsScopesValueHolder<>(holder);
    Assertions.assertSame(holder, value.clientCredentialsScopes("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getClientCredentialsScopesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getClientCredentialsScopes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.clientCredentialsScopesNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getClientCredentialsScopesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getClientCredentialsScopes().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of client credentials scopes of oauth client")
  void test_client_credentials_scopes_value_holder_assign_value_object() {
    Object holder = new Object();
    ClientCredentialsScopesValueHolder<Object> value =
        new ClientCredentialsScopesValueHolder<>(holder);
    ClientCredentialsScopesVO vo = ClientCredentialsScopesVO.from("one");
    Assertions.assertFalse(value.getClientCredentialsScopesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.clientCredentialsScopes(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getClientCredentialsScopesValue().orElseThrow());
    Assertions.assertSame(holder, value.clientCredentialsScopes(Optional.empty()));
    Assertions.assertFalse(value.getClientCredentialsScopesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.clientCredentialsScopes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getClientCredentialsScopesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of client credentials scopes of oauth client against the original")
  void test_client_credentials_scopes_value_holder_read() {
    Object holder = new Object();
    ClientCredentialsScopesValueHolder<Object> value =
        new ClientCredentialsScopesValueHolder<>(holder);
    ClientCredentialsScopesVO vo = ClientCredentialsScopesVO.from("one");
    ClientCredentialsScopesVO other = ClientCredentialsScopesVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getClientCredentialsScopesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readClientCredentialsScopes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readClientCredentialsScopes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.clientCredentialsScopes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readClientCredentialsScopes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readClientCredentialsScopes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of client credentials scopes of oauth client")
  void test_client_credentials_scopes_value_holder_unset() {
    Object holder = new Object();
    ClientCredentialsScopesValueHolder<Object> value =
        new ClientCredentialsScopesValueHolder<>(holder);
    ClientCredentialsScopesVO vo = ClientCredentialsScopesVO.from("one");
    value.clientCredentialsScopes(vo);
    Assertions.assertSame(holder,
        value.unsetClientCredentialsScopesIfMatches("clientCredentialsScopes_other"));
    Assertions.assertTrue(value.getClientCredentialsScopesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetClientCredentialsScopesIfMatches("clientCredentialsScopes"));
    Assertions.assertFalse(value.getClientCredentialsScopesValue().isPresent(),
        "The field name must clear the value");
    value.clientCredentialsScopes(vo);
    Assertions.assertSame(holder, value.unsetClientCredentialsScopes());
    Assertions.assertFalse(value.getClientCredentialsScopesValue().isPresent(),
        "Unset must clear the value");
  }
}
